export function loadIcon(name: IconName, variant?: IconVariant) {
  const variants = Object.prototype.hasOwnProperty.call(iconLoaders,name) ? iconLoaders[name] : undefined;
  variant ??= variants?.color ? 'color' : 'text';
  const loader = variants && Object.prototype.hasOwnProperty.call(variants,variant) ? variants[variant] : undefined;
  return typeof loader === 'function' ? loader() : Promise.reject(new Error('Unknown or unavailable icon variant'));
}

